CREATE TABLE public.webauthn_credentials (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL, credential_id TEXT NOT NULL UNIQUE, public_key TEXT NOT NULL, counter BIGINT NOT NULL DEFAULT 0, device_label TEXT, transports TEXT[], last_used_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX idx_webauthn_credentials_user ON public.webauthn_credentials(user_id); ALTER TABLE public.webauthn_credentials ENABLE ROW LEVEL SECURITY; CREATE POLICY "pk_read_own" ON public.webauthn_credentials FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY "pk_insert_own" ON public.webauthn_credentials FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "pk_update_own" ON public.webauthn_credentials FOR UPDATE TO authenticated USING (auth.uid() = user_id); CREATE POLICY "pk_delete_own" ON public.webauthn_credentials FOR DELETE TO authenticated USING (auth.uid() = user_id);